-- ============================================================
-- Arranjos -- Supabase Schema + Seed
-- Run this ONCE in the Supabase SQL Editor
-- ============================================================

-- 1. Tables
CREATE TABLE IF NOT EXISTS temas (
  num    TEXT PRIMARY KEY,
  titulo TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS congregacoes (
  id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nome TEXT NOT NULL UNIQUE
);
CREATE TABLE IF NOT EXISTS datas (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  tema_num       TEXT    NOT NULL REFERENCES temas(num) ON DELETE CASCADE,
  mes            TEXT    NOT NULL,
  ano            INTEGER NOT NULL,
  mes_idx        INTEGER NOT NULL,
  origem         TEXT    NOT NULL DEFAULT 'usuario',
  congregacao_id BIGINT  REFERENCES congregacoes(id),
  UNIQUE(tema_num, mes_idx, congregacao_id)
);
CREATE TABLE IF NOT EXISTS designacoes (
  ano            INTEGER NOT NULL,
  mes            INTEGER NOT NULL,
  congregacao_id BIGINT  REFERENCES congregacoes(id),
  PRIMARY KEY(ano, mes)
);
CREATE TABLE IF NOT EXISTS discursos (
  id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  congregacao_id BIGINT REFERENCES congregacoes(id),
  data           DATE   NOT NULL,
  orador         TEXT,
  numero         INTEGER,
  titulo         TEXT NOT NULL,
  horario        TEXT,
  tipo           TEXT
);

-- 2. Permissions
ALTER TABLE temas        DISABLE ROW LEVEL SECURITY;
ALTER TABLE congregacoes DISABLE ROW LEVEL SECURITY;
ALTER TABLE datas        DISABLE ROW LEVEL SECURITY;
ALTER TABLE designacoes  DISABLE ROW LEVEL SECURITY;
ALTER TABLE discursos    DISABLE ROW LEVEL SECURITY;
GRANT ALL ON ALL TABLES IN SCHEMA public TO anon;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO anon;

